{
  "name": "BACnet MS/TP 多路复用器",
  "name_en": "BACnet MS/TP Multiplexer",
  "manufacturer": "",
  "description": "用于 BACnet MS/TP（主从/令牌传递）串行总线的通信多路复用组件，负责在总线接口与上层应用之间转发、分发和管理报文。常用于楼宇自动化及实验室集成场景中，对 BACnet 现场控制器、传感器和执行器的总线通信进行接入、调试与测试。",
  "description_en": "A communication multiplexer for BACnet MS/TP (Master-Slave/Token-Passing) serial networks. It forwards, distributes, and manages protocol messages between the bus interface and higher-level applications. It is commonly used in building automation and laboratory integration setups for connecting, testing, and debugging BACnet field controllers, sensors, and actuators.",
  "tag_hints": [
    "BACnet MS/TP",
    "serial fieldbus",
    "building automation",
    "PDU routing",
    "broadcast handling"
  ],
  "actions": [
    {
      "action_name": "auto-close_socket",
      "description": "关闭 MS/TP 通信套接字或相关通信通道。",
      "description_en": "Close the MS/TP communication socket or related communication channels."
    },
    {
      "action_name": "auto-confirmation",
      "description": "处理确认方向的 MS/TP 报文并按目标进行转发。",
      "description_en": "Process confirmation-side MS/TP messages and forward them according to the destination."
    },
    {
      "action_name": "auto-indication",
      "description": "处理指示方向的 MS/TP 报文，并检查广播报文。",
      "description_en": "Process indication-side MS/TP messages and check for broadcast traffic."
    },
    {
      "action_name": "auto-sap_indication",
      "description": "处理服务接入点的指示报文传递。",
      "description_en": "Handle indication message transfer at the service access point."
    },
    {
      "action_name": "auto-sap_confirmation",
      "description": "处理服务接入点的确认报文传递。",
      "description_en": "Handle confirmation message transfer at the service access point."
    },
    {
      "action_name": "auto-atexit_handler",
      "description": "在退出时执行通信清理与关闭操作。",
      "description_en": "Perform communication cleanup and shutdown operations at exit."
    },
    {
      "action_name": "auto-add_actor",
      "description": "添加一个受管理的通信参与对象或通道。",
      "description_en": "Add a managed communication actor or channel."
    },
    {
      "action_name": "auto-del_actor",
      "description": "移除一个受管理的通信参与对象或通道。",
      "description_en": "Remove a managed communication actor or channel."
    },
    {
      "action_name": "auto-actor_error",
      "description": "处理某个通信参与对象的错误状态。",
      "description_en": "Handle an error condition for a communication actor."
    },
    {
      "action_name": "auto-get_actor",
      "description": "获取已注册的通信参与对象或通道。",
      "description_en": "Get a registered communication actor or channel."
    },
    {
      "action_name": "auto-handle_connect",
      "description": "处理通信连接建立事件。",
      "description_en": "Handle a communication connection event."
    },
    {
      "action_name": "auto-readable",
      "description": "判断通信通道当前是否可读。",
      "description_en": "Determine whether the communication channel is currently readable."
    },
    {
      "action_name": "auto-handle_read",
      "description": "处理从总线或通信通道读取到的数据。",
      "description_en": "Handle data read from the bus or communication channel."
    },
    {
      "action_name": "auto-writable",
      "description": "判断通信通道当前是否可写。",
      "description_en": "Determine whether the communication channel is currently writable."
    },
    {
      "action_name": "auto-handle_write",
      "description": "处理向总线或通信通道写出的数据。",
      "description_en": "Handle data written to the bus or communication channel."
    },
    {
      "action_name": "auto-handle_close",
      "description": "处理通信通道关闭事件。",
      "description_en": "Handle a communication channel close event."
    },
    {
      "action_name": "auto-handle_error",
      "description": "处理通信过程中的通用错误。",
      "description_en": "Handle a general communication error."
    }
  ]
}

